export const REQUEST_NAMESPACE = 'cattle-multisite-system';
export const REQUEST_COLLECTION_URL = '/v1/multisite.focusnet.de.multisiteclusterrequests';
export const CUSTOMER_COLLECTION_URL = '/v1/multisite.focusnet.de.multisitecustomers';

// Erste Version = Vorbelegung im Wizard. Serverseitig freigegeben in customer-platform
// multisite_request_contract.py (_DEFAULT_KUBERNETES_VERSIONS) — beide Listen gemeinsam pflegen.
export const KUBERNETES_VERSIONS = Object.freeze(['v1.35.7+rke2r1', 'v1.34.4+rke2r1']);
export const SIZE_CLASSES = Object.freeze({
  S: {
    controlPlane: {
      cpu: 2, memoryGiB: 8, diskGiB: 40, countBerlin1: 1, countBerlin2: 1,
    },
    worker: { cpu: 2, memoryGiB: 8, diskGiB: 40, countBerlin1: 0, countBerlin2: 0 },
    controlPlaneIsWorker: true,
  },
  M: {
    controlPlane: {
      cpu: 4, memoryGiB: 16, diskGiB: 40, countBerlin1: 1, countBerlin2: 1,
    },
    worker: { cpu: 4, memoryGiB: 16, diskGiB: 40, countBerlin1: 0, countBerlin2: 0 },
    controlPlaneIsWorker: true,
  },
  L: {
    controlPlane: {
      cpu: 4, memoryGiB: 16, diskGiB: 40, countBerlin1: 1, countBerlin2: 1,
    },
    worker: { cpu: 4, memoryGiB: 16, diskGiB: 40, countBerlin1: 3, countBerlin2: 2 },
    controlPlaneIsWorker: false,
  },
  XL: {
    controlPlane: {
      cpu: 6, memoryGiB: 26, diskGiB: 40, countBerlin1: 1, countBerlin2: 1,
    },
    worker: { cpu: 6, memoryGiB: 26, diskGiB: 40, countBerlin1: 4, countBerlin2: 4 },
    controlPlaneIsWorker: false,
  },
});
export const ZONE_LABEL = /^[a-z0-9]([a-z0-9-]{0,22}[a-z0-9])?$/;

// Gestreckter Ceph-Block-Storage: Bestellgröße in GB (spec.cephStorageGiB). Serverseitig
// identisch geprüft in customer-platform multisite_request_contract.py — gemeinsam pflegen.
export const CEPH_STORAGE_GIB_MIN = 100;
export const CEPH_STORAGE_GIB_MAX = 20000;
export const CEPH_STORAGE_GIB_STEP = 10;
export const CEPH_STORAGE_GIB_DEFAULT = 500;

const UUID = /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i;
const CLUSTER_NAME = /^[a-z0-9]([-a-z0-9]*[a-z0-9])?$/;

function items(response: any): any[] {
  const value = response?.data?.data ?? response?.data ?? response;

  return Array.isArray(value) ? value : [];
}

function requireUuid(value: unknown, label: string): string {
  const candidate = `${ value || '' }`.trim();

  if (!UUID.test(candidate)) {
    throw new Error(`${ label } ist keine gültige UUID.`);
  }

  return candidate;
}

function requireClosedObject(value: unknown, keys: string[], label: string): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`${ label } enthält zusätzliche oder fehlende Felder.`);
  }

  const actual = Object.keys(value).sort();
  const expected = [...keys].sort();

  if (actual.length !== expected.length || actual.some((key, index) => key !== expected[index])) {
    throw new Error(`${ label } enthält zusätzliche oder fehlende Felder.`);
  }

  return value as Record<string, unknown>;
}

function requireInteger(value: unknown, label: string, minimum: number, maximum: number): number {
  if (!Number.isInteger(value) || (value as number) < minimum || (value as number) > maximum) {
    throw new Error(`${ label } muss eine Ganzzahl zwischen ${ minimum } und ${ maximum } sein.`);
  }

  return value as number;
}

export const NODE_SIZE_FIELD_RULES = Object.freeze([
  { path: 'controlPlane.cpu', label: 'Control Plane CPU', min: 2, max: 32 },
  { path: 'controlPlane.memoryGiB', label: 'Control Plane RAM', min: 4, max: 256 },
  { path: 'controlPlane.diskGiB', label: 'Control Plane Disk', min: 40, max: 1000 },
  { path: 'controlPlane.countBerlin1', label: 'Control-Plane-Anzahl Berlin 1', min: 1, max: 7 },
  { path: 'controlPlane.countBerlin2', label: 'Control-Plane-Anzahl Berlin 2', min: 1, max: 7 },
  { path: 'worker.cpu', label: 'Worker CPU', min: 2, max: 32 },
  { path: 'worker.memoryGiB', label: 'Worker RAM', min: 4, max: 256 },
  { path: 'worker.diskGiB', label: 'Worker Disk', min: 40, max: 1000 },
  { path: 'worker.countBerlin1', label: 'Worker-Anzahl Berlin 1', min: 0, max: 50 },
  { path: 'worker.countBerlin2', label: 'Worker-Anzahl Berlin 2', min: 0, max: 50 },
] as const);

const COMBINED_RULE_MESSAGE = 'Ohne Berliner Worker müssen die Control Planes auch als Worker genutzt werden.';

// etcd-Stimmen = Control Planes Berlin 1 + Berlin 2 + 1 (fester Hannover-Witness).
// Nur eine gerade Berliner Summe hält die Stimmenzahl ungerade und das Quorum
// mehrheitsfähig. Wortgleich in i18n/de-de.yaml (quorumInvalid) gepflegt.
const QUORUM_RULE_MESSAGE = 'Die Summe der Control-Plane-Nodes aus Berlin 1 und Berlin 2 muss gerade sein, damit die etcd-Stimmenzahl mit dem festen Hannover-Witness ungerade bleibt — z. B. 1 + 1 (3 Stimmen) oder 2 + 2 (5 Stimmen).';

const CONTROL_PLANE_BASE_KEYS = Object.freeze(['cpu', 'memoryGiB', 'diskGiB']);
const CONTROL_PLANE_COUNT_KEYS = Object.freeze(['countBerlin1', 'countBerlin2']);

// Die Control-Plane-Anzahlen je Berlin-Site sind als PAAR optional: fehlen beide,
// gilt der Serververtrag-Default 1/1 (abwärtskompatibel zum Server ohne die
// Felder). Ein einzelnes der beiden Felder bleibt ein Strukturfehler.
function requireControlPlaneObject(value: unknown): Record<string, unknown> {
  const hasCounts = !!value && typeof value === 'object' && !Array.isArray(value) &&
    CONTROL_PLANE_COUNT_KEYS.some((key) => key in (value as Record<string, unknown>));

  return requireClosedObject(
    value,
    hasCounts ? [...CONTROL_PLANE_BASE_KEYS, ...CONTROL_PLANE_COUNT_KEYS] : [...CONTROL_PLANE_BASE_KEYS],
    'Control-Plane-Größe',
  );
}

function nodeSizeRule(path: string) {
  const rule = NODE_SIZE_FIELD_RULES.find((entry) => entry.path === path);

  if (!rule) {
    throw new Error(`Unbekannte Node-Größen-Regel: ${ path }`);
  }

  return rule;
}

function requireRuled(value: unknown, path: string): number {
  const rule = nodeSizeRule(path);

  return requireInteger(value, rule.label, rule.min, rule.max);
}

function requireNodeSizes(value: unknown): Record<string, unknown> {
  const nodeSizes = requireClosedObject(
    value,
    ['controlPlane', 'worker', 'controlPlaneIsWorker'],
    'Node-Größen',
  );
  const controlPlane = requireControlPlaneObject(nodeSizes.controlPlane);
  const worker = requireClosedObject(
    nodeSizes.worker,
    ['cpu', 'memoryGiB', 'diskGiB', 'countBerlin1', 'countBerlin2'],
    'Worker-Größe',
  );

  if (typeof nodeSizes.controlPlaneIsWorker !== 'boolean') {
    throw new Error('Control Planes als Worker muss ein Boolean sein.');
  }

  const controlPlaneResult: Record<string, number> = {
    cpu: requireRuled(controlPlane.cpu, 'controlPlane.cpu'),
    memoryGiB: requireRuled(controlPlane.memoryGiB, 'controlPlane.memoryGiB'),
    diskGiB: requireRuled(controlPlane.diskGiB, 'controlPlane.diskGiB'),
  };
  const controlPlaneCountBerlin1 = requireRuled(controlPlane.countBerlin1 ?? 1, 'controlPlane.countBerlin1');
  const controlPlaneCountBerlin2 = requireRuled(controlPlane.countBerlin2 ?? 1, 'controlPlane.countBerlin2');

  // Abwärtskompatibler Serververtrag: der Default 1/1 wird NICHT gesendet —
  // ein noch nicht aktualisierter Server ergänzt fehlende Felder als 1/1.
  if (controlPlaneCountBerlin1 !== 1 || controlPlaneCountBerlin2 !== 1) {
    controlPlaneResult.countBerlin1 = controlPlaneCountBerlin1;
    controlPlaneResult.countBerlin2 = controlPlaneCountBerlin2;
  }

  const result = {
    controlPlane: controlPlaneResult,
    worker: {
      cpu: requireRuled(worker.cpu, 'worker.cpu'),
      memoryGiB: requireRuled(worker.memoryGiB, 'worker.memoryGiB'),
      diskGiB: requireRuled(worker.diskGiB, 'worker.diskGiB'),
      countBerlin1: requireRuled(worker.countBerlin1, 'worker.countBerlin1'),
      countBerlin2: requireRuled(worker.countBerlin2, 'worker.countBerlin2'),
    },
    controlPlaneIsWorker: nodeSizes.controlPlaneIsWorker,
  };

  if ((controlPlaneCountBerlin1 + controlPlaneCountBerlin2) % 2 !== 0) {
    throw new Error(QUORUM_RULE_MESSAGE);
  }
  if (result.worker.countBerlin1 + result.worker.countBerlin2 === 0 && !result.controlPlaneIsWorker) {
    throw new Error(COMBINED_RULE_MESSAGE);
  }

  return result;
}

// Feldweise Live-Validierung fuer den Wizard (analog zur nativen Rancher-
// Cluster-Erstellung: Fehler am Feld statt erst beim Absenden). Dieselben
// Regeln wie requireNodeSizes — gemeinsame Tabelle, keine Doppelpflege.
export function nodeSizeFieldErrors(value: unknown): Record<string, string> {
  const errors: Record<string, string> = {};
  let nodeSizes: Record<string, unknown>;
  let controlPlane: Record<string, unknown>;
  let worker: Record<string, unknown>;

  try {
    nodeSizes = requireClosedObject(
      value,
      ['controlPlane', 'worker', 'controlPlaneIsWorker'],
      'Node-Größen',
    );
    controlPlane = requireControlPlaneObject(nodeSizes.controlPlane);
    worker = requireClosedObject(
      nodeSizes.worker,
      ['cpu', 'memoryGiB', 'diskGiB', 'countBerlin1', 'countBerlin2'],
      'Worker-Größe',
    );
    if (typeof nodeSizes.controlPlaneIsWorker !== 'boolean') {
      throw new Error('Control Planes als Worker muss ein Boolean sein.');
    }
  } catch (structureError: any) {
    return { _structure: `${ structureError?.message || structureError }` };
  }

  // Fehlende Control-Plane-Anzahlen gelten wie im Serververtrag als 1/1.
  const groups: Record<string, Record<string, unknown>> = {
    controlPlane: {
      ...controlPlane,
      countBerlin1: controlPlane.countBerlin1 ?? 1,
      countBerlin2: controlPlane.countBerlin2 ?? 1,
    },
    worker,
  };

  for (const rule of NODE_SIZE_FIELD_RULES) {
    const [group, field] = rule.path.split('.');

    try {
      requireRuled(groups[group][field], rule.path);
    } catch (fieldError: any) {
      errors[rule.path] = `${ fieldError?.message || fieldError }`;
    }
  }

  if (
    !errors['controlPlane.countBerlin1'] && !errors['controlPlane.countBerlin2'] &&
    ((groups.controlPlane.countBerlin1 as number) + (groups.controlPlane.countBerlin2 as number)) % 2 !== 0
  ) {
    errors['controlPlane.quorum'] = QUORUM_RULE_MESSAGE;
  }

  const counts = [worker.countBerlin1, worker.countBerlin2];

  if (
    !errors['worker.countBerlin1'] && !errors['worker.countBerlin2'] &&
    counts[0] === 0 && counts[1] === 0 && nodeSizes.controlPlaneIsWorker !== true
  ) {
    errors.controlPlaneIsWorker = COMBINED_RULE_MESSAGE;
  }

  return errors;
}

export function isValidNodeSizes(value: unknown): boolean {
  try {
    requireNodeSizes(value);

    return true;
  } catch (_error) {
    return false;
  }
}

const CEPH_STORAGE_RULE_MESSAGE = `Die Storage-Größe muss eine Ganzzahl zwischen ${ CEPH_STORAGE_GIB_MIN } ` +
  `und ${ CEPH_STORAGE_GIB_MAX } GB in ${ CEPH_STORAGE_GIB_STEP }er-Schritten sein.`;

// Feldweise Live-Validierung fuer den Wizard; createRequest wirft dieselbe Meldung.
export function cephStorageFieldError(value: unknown): string | null {
  if (
    !Number.isInteger(value) ||
    (value as number) < CEPH_STORAGE_GIB_MIN ||
    (value as number) > CEPH_STORAGE_GIB_MAX ||
    (value as number) % CEPH_STORAGE_GIB_STEP !== 0
  ) {
    return CEPH_STORAGE_RULE_MESSAGE;
  }

  return null;
}

function randomUuid(): string {
  const candidate = globalThis?.crypto?.randomUUID?.();

  if (!candidate) {
    throw new Error('Der Browser kann keine sichere Request-ID erzeugen.');
  }

  return candidate;
}

export async function listRequests(store: any): Promise<any[]> {
  return items(await store.dispatch('management/request', {
    url:    REQUEST_COLLECTION_URL,
    method: 'GET',
  }));
}

export async function listCustomers(store: any): Promise<any[]> {
  const result = items(await store.dispatch('management/request', {
    url:    CUSTOMER_COLLECTION_URL,
    method: 'GET',
  }));

  return result.filter((customer) => customer?.spec?.status === 'active');
}

export async function createRequest(
  store: any,
  form: any,
  ids: { requestId?: string; idempotencyKey?: string } = {},
): Promise<any> {
  const customerUuid = requireUuid(form?.customerUuid, 'Kunde');
  const clusterName = `${ form?.clusterName || '' }`.trim();
  const kubernetesVersion = `${ form?.kubernetesVersion || '' }`.trim();
  const nodeSizes = requireNodeSizes(form?.nodeSizes);
  const networkMode = `${ form?.networkMode || 'new' }`.trim();
  const requestId = requireUuid(ids.requestId || randomUuid(), 'Request-ID');
  const idempotencyKey = requireUuid(ids.idempotencyKey || randomUuid(), 'Idempotenzschlüssel');

  if (clusterName.length > 63 || !CLUSTER_NAME.test(clusterName)) {
    throw new Error('Der Clustername muss ein gültiger Kubernetes-Name mit höchstens 63 Zeichen sein.');
  }
  if (!KUBERNETES_VERSIONS.includes(kubernetesVersion)) {
    throw new Error('Die gewählte Kubernetes-Version ist nicht freigegeben.');
  }
  if (networkMode !== 'new' && networkMode !== 'existing') {
    throw new Error('Der Netzwerkmodus ist nicht freigegeben.');
  }

  const spec: Record<string, unknown> = {
    requestId,
    customerUuid,
    clusterName,
    kubernetesVersion,
    nodeSizes,
    networkMode,
    idempotencyKey,
  };

  if (networkMode === 'existing') {
    // Ziel-Zone kommt aus dem Katalog (MultisiteCustomer.spec.routingZones);
    // der Server prüft Eigentum und Slot-Identität erneut fail-closed.
    const fabricVrfId = requireUuid(form?.fabricVrfId, 'Routing-Zone');
    const mspId = Number(form?.mspId);

    if (!Number.isInteger(mspId) || mspId <= 0) {
      throw new Error('Die gewählte Routing-Zone trägt keine gültige MSP-ID.');
    }
    spec.fabricVrfId = fabricVrfId;
    spec.mspId = mspId;
  }

  if (networkMode === 'new') {
    const zoneLabel = `${ form?.zoneLabel || '' }`.trim();

    if (zoneLabel) {
      if (!ZONE_LABEL.test(zoneLabel)) {
        throw new Error('Die Zonen-Bezeichnung darf 1–24 Zeichen aus Kleinbuchstaben, Ziffern und Bindestrichen (nicht am Rand) enthalten.');
      }
      spec.zoneLabel = zoneLabel;
    }
  }

  // Storage nur auf Bestellung: ohne Schalter kein Feld im Spec.
  if (form?.cephStorageEnabled === true) {
    const storageError = cephStorageFieldError(form?.cephStorageGiB);

    if (storageError) {
      throw new Error(storageError);
    }
    spec.cephStorageGiB = form.cephStorageGiB as number;
  }

  const data = {
    apiVersion: 'multisite.focusnet.de/v1alpha1',
    kind:       'MultisiteClusterRequest',
    metadata:   {
      name:      `msr-${ requestId }`,
      namespace: REQUEST_NAMESPACE,
    },
    spec,
  };

  return store.dispatch('management/request', {
    url:    REQUEST_COLLECTION_URL,
    method: 'POST',
    data,
  });
}
