<script>
import {
  ALLOWED_GETTER, LOADING_GETTER, refreshAccess,
} from '../lib/gate';
import ProvisionWizard from './ProvisionWizard.vue';

// Route-Gate für BEIDE Plugin-Routen (global + cluster-scoped). Der Wizard wird erst
// instanziiert, wenn `multisiteAccess/allowed` wahr ist — vorher läuft dessen
// mounted() nicht, es werden also weder Kundenkatalog noch Requeststatus geladen,
// und der Wizard blitzt nicht kurz auf.
//
// Bewusst KEIN lokaler `allowed`-State: Die Anzeige liest direkt den reaktiven
// Store-Getter. Ein Logout (oder jedes andere `invalidate`) setzt den Getter synchron
// auf false und unmountet den Wizard damit sofort — ein kopierter lokaler Wert würde
// genau das verpassen.
export default {
  name:       'MultisiteGateGuard',
  layout:     'plain',
  components: { ProvisionWizard },

  computed: {
    allowed() {
      return this.$store.getters[ALLOWED_GETTER] === true;
    },
    // Solange geprüft wird, weder Wizard noch Sperrseite zeigen.
    checking() {
      return this.$store.getters[LOADING_GETTER] === true;
    },
  },

  created() {
    // Frische Entscheidung bei jedem Aufruf der Route. `refresh` setzt synchron
    // deny+loading, bevor es fragt — der Default ist also auch hier verweigert.
    refreshAccess(this.$store);
  },
};
</script>

<template>
  <div>
    <ProvisionWizard v-if="allowed" />
    <div
      v-else-if="checking"
      class="msp-gate"
    >
      Berechtigung wird geprüft …
    </div>
    <div
      v-else
      class="msp-gate msp-gate--denied"
      role="alert"
    >
      <h1>Kein Zugriff</h1>
      <p>
        Der Multi-Site Cluster Provisioner ist einer eingeschränkten Benutzergruppe
        vorbehalten. Ihr Konto gehört dieser Gruppe nicht an.
      </p>
      <p>
        Wenn Sie den Zugang benötigen, wenden Sie sich bitte an Ihren Ansprechpartner
        bei focusnet. Nach der Aufnahme in die Gruppe müssen Sie sich einmal ab- und
        wieder anmelden.
      </p>
    </div>
  </div>
</template>

<style lang="scss" scoped>
.msp-gate { padding: 1.5rem 2rem; font-size: 16px; max-width: 80ch; }
.msp-gate--denied h1 { font-size: 1.5rem; margin: 0 0 .5rem; }
.msp-gate--denied p { line-height: 1.5; }
</style>
